<?php
session_name('anytour_manager_panel');
session_set_cookie_params(['lifetime'=>60*60*12,'path'=>'/max-search/manager/','secure'=>true,'httponly'=>true,'samesite'=>'Lax']);
session_start();
?><!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>AnyTour — диалоги</title><style>
*{box-sizing:border-box}body{margin:0;font:15px/1.4 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:#f5f6f8;color:#18202a}.app{height:100vh;display:grid;grid-template-columns:360px 1fr}.sidebar{background:#fff;border-right:1px solid #e6e8eb;display:flex;flex-direction:column;min-width:0}.top{padding:14px;border-bottom:1px solid #eee}.brand{font-weight:700;font-size:18px}.row{display:flex;justify-content:space-between;gap:8px}.projectSelect{width:100%;margin-top:10px;padding:9px 10px;border:1px solid #d8dde3;border-radius:10px;background:#fff;font:inherit}.tabs{display:flex;gap:6px;margin-top:10px;overflow:auto}.tabs button,.actions button,.send button{border:0;border-radius:10px;padding:9px 11px;background:#eef1f4;cursor:pointer;white-space:nowrap}.tabs button.active,.actions button.primary,.send button{background:#111827;color:#fff}.tabCount{display:inline-block;min-width:18px;margin-left:4px;padding:1px 5px;border-radius:999px;background:#dfe4ea;font-size:11px}.tabs button.active .tabCount{background:#374151}.list{overflow:auto;flex:1}.item{padding:12px 14px;border-bottom:1px solid #f0f1f2;cursor:pointer;position:relative}.item:hover,.item.active{background:#f7f9fc}.item.unread{background:#fffdf2}.name{font-weight:600}.muted{color:#7b8490;font-size:13px}.context{display:flex;gap:5px;flex-wrap:wrap;margin-top:5px}.tag{font-size:11px;padding:2px 6px;border-radius:999px;background:#eef1f4;color:#5f6874}.preview{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:5px;padding-right:28px}.unreadCount{position:absolute;right:14px;bottom:13px;min-width:22px;height:22px;padding:2px 6px;border-radius:999px;background:#111827;color:#fff;font-size:12px;text-align:center}.badge{font-size:11px;padding:3px 7px;border-radius:999px;background:#eef1f4}.badge.waiting_manager{background:#fff1c2}.badge.manager{background:#dff7e8}.chat{display:flex;flex-direction:column;min-width:0}.chatHead{background:#fff;border-bottom:1px solid #e6e8eb;padding:12px 16px;display:flex;justify-content:space-between;align-items:center;gap:12px}.actions{display:flex;gap:7px;flex-wrap:wrap}.messages{flex:1;overflow:auto;padding:18px;display:flex;flex-direction:column;gap:10px}.msg{max-width:min(760px,82%);padding:10px 12px;border-radius:14px;background:#fff;box-shadow:0 1px 2px #0000000d;white-space:pre-wrap;word-break:break-word}.msg.inbound{align-self:flex-start}.msg.outbound{align-self:flex-end;background:#e8f3ff}.msg.manager{background:#dcfce7}.msg .meta{font-size:11px;color:#7c8794;margin-top:5px}.composer{background:#fff;border-top:1px solid #e6e8eb;padding:12px;display:flex;gap:8px}.composer textarea{flex:1;resize:none;min-height:44px;max-height:120px;border:1px solid #d8dde3;border-radius:12px;padding:10px 12px;font:inherit}.empty{margin:auto;color:#8a929b}.login{position:fixed;inset:0;background:#f5f6f8;display:flex;align-items:center;justify-content:center;padding:20px;z-index:5}.loginCard{width:min(380px,100%);background:#fff;padding:24px;border-radius:18px;box-shadow:0 10px 30px #0001}.login input{width:100%;padding:12px;margin-top:10px;border:1px solid #d7dce2;border-radius:10px;font:inherit}.login button{width:100%;margin-top:14px;padding:12px;border:0;border-radius:10px;background:#111827;color:#fff;font:inherit}.hidden{display:none!important}.back{display:none}@media(max-width:760px){.app{display:block}.sidebar{height:100vh;border:0}.chat{position:fixed;inset:0;background:#f5f6f8;transform:translateX(100%);transition:.18s}.chat.open{transform:none}.back{display:inline-block;border:0;background:none;font-size:24px}.chatHead{padding:10px}.msg{max-width:90%}}
</style></head><body>
<div id="login" class="login hidden"><form id="loginForm" class="loginCard"><div class="brand">AnyTour · Менеджер</div><div class="muted">Единая панель диалогов</div><input id="loginInput" autocomplete="username" placeholder="Логин" required><input id="passInput" type="password" autocomplete="current-password" placeholder="Пароль" required><button>Войти</button><div id="loginError" class="muted" style="margin-top:10px"></div></form></div>
<div class="app"><aside class="sidebar"><div class="top"><div class="row"><div class="brand">Диалоги</div><div id="me" class="muted"></div></div><select id="project" class="projectSelect"></select><div class="tabs"><button data-queue="waiting" class="active">Ждут менеджера <span id="waitingCount" class="tabCount hidden">0</span></button><button data-queue="mine">Мои <span id="mineCount" class="tabCount hidden">0</span></button><button data-queue="all">Все доступные</button><button data-queue="closed">Закрытые</button></div></div><div id="list" class="list"></div></aside><main id="chat" class="chat"><div class="chatHead"><div style="display:flex;align-items:center;gap:8px"><button id="back" class="back">‹</button><div><div id="chatTitle" class="brand">Выберите диалог</div><div id="chatMeta" class="muted"></div></div></div><div id="actions" class="actions"></div></div><div id="messages" class="messages"><div class="empty">Диалог не выбран</div></div><form id="composer" class="composer hidden"><textarea id="text" placeholder="Ответ менеджера"></textarea><button class="send">Отправить</button></form></main></div>
<script>
const S={csrf:'',manager:null,current:0,queue:'waiting',project:'*',projects:[],lastUnread:0,canSound:false};const $=id=>document.getElementById(id);
async function api(action,data={}){const r=await fetch('api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,csrf:S.csrf,...data})});const j=await r.json().catch(()=>({ok:false,error:'bad_response'}));if(r.status===401&&action!=='login'){showLogin();throw new Error('unauthorized')}return j}
function showLogin(){$('login').classList.remove('hidden')}function hideLogin(){$('login').classList.add('hidden')}
async function boot(){const j=await api('me').catch(()=>null);if(!j||!j.ok){showLogin();return}ready(j)}
function ready(j){S.csrf=j.csrf;S.manager=j.manager;S.projects=j.projects||j.manager.projects||[];hideLogin();$('me').textContent=(j.manager.display_name||j.manager.login)+(j.manager.role==='admin'?' · admin':'');renderProjects();refresh()}
function renderProjects(){const s=$('project');s.innerHTML='';if(S.projects.length>1){const all=document.createElement('option');all.value='*';all.textContent='Все проекты';s.appendChild(all)}S.projects.forEach(p=>{const o=document.createElement('option');o.value=p.project_key;o.textContent=p.display_name;s.appendChild(o)});if(S.projects.length===1)S.project=S.projects[0].project_key;else if(!S.project)S.project='*';s.value=S.project;s.classList.toggle('hidden',S.projects.length<=1)}
$('project').onchange=()=>{S.project=$('project').value;resetChat();refresh()};
$('loginForm').onsubmit=async e=>{e.preventDefault();$('loginError').textContent='';const j=await api('login',{login:$('loginInput').value,password:$('passInput').value});if(!j.ok){$('loginError').textContent='Неверный логин или пароль';return}S.canSound=true;ready(j)};
document.addEventListener('click',()=>{S.canSound=true},{once:true});
document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');S.queue=b.dataset.queue;resetChat();loadList()});
function resetChat(){S.current=0;$('chat').classList.remove('open');$('chatTitle').textContent='Выберите диалог';$('chatMeta').textContent='';$('messages').innerHTML='<div class="empty">Диалог не выбран</div>';$('actions').innerHTML='';$('composer').classList.add('hidden')}
function esc(s){const d=document.createElement('div');d.textContent=s??'';return d.innerHTML}function statusText(s){return{ai:'AI',waiting_manager:'Ждёт менеджера',manager:'У менеджера',closed:'Закрыт'}[s]||s}
async function refresh(){await Promise.all([loadList(),loadCounts()])}
async function loadCounts(){const j=await api('counts',{project_key:S.project});if(!j.ok)return;const waiting=j.counts?.waiting||{count:0,unread:0},mine=j.counts?.mine||{count:0,unread:0};setTabCount('waitingCount',waiting.count);setTabCount('mineCount',mine.unread);const total=Number(waiting.unread||0)+Number(mine.unread||0);document.title=total>0?`(${total}) AnyTour — диалоги`:'AnyTour — диалоги';if(total>S.lastUnread&&S.lastUnread>=0)beep();S.lastUnread=total}
function setTabCount(id,n){const e=$(id);e.textContent=String(n||0);e.classList.toggle('hidden',!Number(n))}
function beep(){if(!S.canSound)return;try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;const a=new A(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.value=880;g.gain.value=.035;o.start();o.stop(a.currentTime+.12);o.onended=()=>a.close()}catch(e){}}
async function loadList(){const j=await api('list',{queue:S.queue,project_key:S.project});if(!j.ok)return;const box=$('list');box.innerHTML='';j.conversations.forEach(c=>{const unread=Number(c.unread_count||0);const el=document.createElement('div');el.className='item'+(Number(c.id)===S.current?' active':'')+(unread?' unread':'');const project=c.project_name||c.project_key||'';const source=c.source_name||'';el.innerHTML=`<div class="row"><span class="name">${esc(c.display_name||'Турист')}</span><span class="badge ${esc(c.status)}">${esc(statusText(c.status))}</span></div><div class="context">${project?`<span class="tag">${esc(project)}</span>`:''}${source?`<span class="tag">${esc(source)}</span>`:''}<span class="tag">${esc((c.channel||'').toUpperCase())}</span></div><div class="muted">${esc(c.last_message_at||c.started_at||'')}</div><div class="preview">${esc(c.last_text||'')}</div>${unread?`<span class="unreadCount">${unread}</span>`:''}`;el.onclick=()=>openChat(c.id);box.appendChild(el)});if(!j.conversations.length)box.innerHTML='<div class="empty" style="padding:30px;text-align:center">Здесь пока нет диалогов</div>'}
async function openChat(id){S.current=Number(id);const j=await api('detail',{conversation_id:S.current});if(!j.ok)return;const c=j.conversation;$('chat').classList.add('open');$('chatTitle').textContent=c.display_name||'Турист';const ctx=[c.project_name||c.project_key,c.source_name,(c.channel||'').toUpperCase(),statusText(c.status),c.manager_name||''].filter(Boolean);$('chatMeta').textContent=ctx.join(' · ');const box=$('messages');box.innerHTML='';j.messages.forEach(m=>{const d=document.createElement('div');d.className=`msg ${m.direction} ${m.sender_type==='manager'?'manager':''}`;const body=document.createElement('div');body.textContent=m.text||'';const meta=document.createElement('div');meta.className='meta';meta.textContent=`${m.sender_type==='customer'?'Клиент':m.sender_type==='manager'?'Менеджер':'AI'} · ${m.created_at}`;d.append(body,meta);box.appendChild(d)});box.scrollTop=box.scrollHeight;renderActions(c);loadCounts();loadList()}
function renderActions(c){const a=$('actions');a.innerHTML='';const own=Number(c.manager_id)===Number(S.manager.id)&&c.status==='manager';if((c.status==='waiting_manager'||c.status==='ai')&&!c.manager_id)btn('Взять','primary',()=>change('take'));if(own){btn('Вернуть AI','',()=>change('release'));btn('Закрыть','',()=>{if(confirm('Закрыть этот диалог? Его можно будет восстановить из раздела «Закрытые».'))change('close')})}if(c.status==='closed')btn('Переоткрыть','primary',()=>change('reopen'));$('composer').classList.toggle('hidden',!own)}function btn(t,cl,fn){const b=document.createElement('button');b.type='button';b.className=cl;b.textContent=t;b.onclick=fn;$('actions').appendChild(b)}async function change(action){const j=await api(action,{conversation_id:S.current});if(j.ok){await openChat(S.current);refresh()}}
$('composer').onsubmit=async e=>{e.preventDefault();const t=$('text').value.trim();if(!t)return;const j=await api('send',{conversation_id:S.current,text:t});if(j.ok){$('text').value='';await openChat(S.current);refresh()}};$('text').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('composer').requestSubmit()}};$('back').onclick=()=>$('chat').classList.remove('open');setInterval(()=>{if(S.manager){loadList();loadCounts();if(S.current)openChat(S.current)}},5000);boot();
</script></body></html>
